    private boolean isApplicantValidated() {
        if (this.binding.includePD.poolingQuestionIncludeLay.poolingQuestion.getVisibility() == 0 && this.binding.includePD.poolingQuestionIncludeLay.partDetailRg.getCheckedRadioButtonId() == -1) {
            this.commonUtilClass.displayAlertWithTitleAndMessage(requireContext(), "Alert", "Please verify Pooling Station Details");
            return false;
        }
        if (this.binding.includePD.dobRg.getCheckedRadioButtonId() == -1) {
            showdialog("Alert", "Please verify personal details");
            return false;
        }
        if (this.countsor.equalsIgnoreCase("Y") && !this.isCheckDSE) {
            showdialog("Alert", "Please check DSE details matched or not");
            return false;
        }
        if (this.binding.addrRg.getCheckedRadioButtonId() == -1) {
            showdialog("Alert", "Please verify address");
            return false;
        }
        if (this.binding.applicantFoundRg.getCheckedRadioButtonId() == -1) {
            showdialog("Alert", "Please verify if applicant was present");
            return false;
        }
        if (this.binding.mismatchlayout.detailsCorrectRg.getCheckedRadioButtonId() == -1) {
            showdialog("Alert", "Please verify if all details matched");
            return false;
        }
        if (this.binding.annexureVerification.getVisibility() == 0 && this.binding.annexureDetailRg.getCheckedRadioButtonId() == -1) {
            showdialog("Alert", "Please verify if all details matched");
            return false;
        }
        if (this.binding.sectionNoName.getSelectedItem().toString().equals("Select Section No. & Name")) {
            showdialog("Alert", "Select Section Number");
            return false;
        }
        if (this.countsor.equals("Y") && this.binding.includePD.poolingQuestionIncludeLay.partDetailRg.getCheckedRadioButtonId() == -1) {
            this.commonUtilClass.displayAlertWithTitleAndMessage(requireContext(), "Alert", "Please verify Pooling Station Details");
            return false;
        }
        if (isDecalarationEnabled() && TextUtils.isEmpty(this.binding.declarationPreview.dfETfatherName.getText().toString())) {
            showdialog("Alert", "Please enter father name in declaration form");
            return false;
        }
        if (isDecalarationEnabled() && TextUtils.isEmpty(this.binding.declarationPreview.dfETmotherName.getText().toString())) {
            showdialog("Alert", "Please enter mother name in declaration form");
            return false;
        }
        if (isDecalarationEnabled() && this.binding.declarationPreview.dfElectorPresentRG.getCheckedRadioButtonId() == -1) {
            showdialog("Alert", "Please select SIR year in declaration form");
            return false;
        }
        if (isDecalarationEnabled() && this.binding.declarationPreview.dfRgsearchRG.getCheckedRadioButtonId() == -1) {
            showdialog("Alert", "Please select any one category in declaration form");
            return false;
        }
        if (isDecalarationEnabled() && TextUtils.isEmpty(this.decsirf8DeclSignature)) {
            showdialog("Alert", "Please upload BLO signature in declaration form");
            return false;
        }
        if (this.binding.mismatchlayout.verifiedNo.isChecked() && this.binding.mismatchlayout.remarkNo.getVisibility() == 0 && this.binding.mismatchlayout.noremark.getText().toString().isEmpty()) {
            this.commonUtilClass.displayAlertWithTitleAndMessage(requireContext(), "Alert", "Please enter remark and mention mismatch information.");
            return false;
        }
        if (this.binding.oldepicCorrectRg.getCheckedRadioButtonId() != -1) {
            return true;
        }
        this.commonUtilClass.displayAlertWithTitleAndMessage(requireContext(), "Alert", "Please verify old EPIC information.");
        return false;
    }

