    private void checkRemarkVisibility() {
        if (!TextUtils.isEmpty(this.countcor) && this.countcor.equalsIgnoreCase("Y")) {
            if (this.binding.addCoeSame.isChecked() && this.binding.mismatchlayout.verifiedYes.isChecked()) {
                this.binding.remarkTv.setEnabled(true);
                this.binding.anyotherremark.remarkll.setVisibility(8);
                this.binding.remarkTv.setText(Constants.FOUND_CORRECT);
                return;
            } else {
                this.binding.anyotherremark.remarkll.setVisibility(0);
                this.binding.remarkTv.setText(Constants.FOUND_INCORRECT);
                this.binding.remarkTv.setEnabled(false);
                return;
            }
        }
        if (this.binding.addrSame.isChecked() && this.binding.mismatchlayout.verifiedYes.isChecked()) {
            this.binding.remarkTv.setEnabled(true);
            this.binding.anyotherremark.remarkll.setVisibility(8);
            this.binding.remarkTv.setText(Constants.FOUND_CORRECT);
        } else {
            this.binding.anyotherremark.remarkll.setVisibility(0);
            this.binding.remarkTv.setText(Constants.FOUND_INCORRECT);
            this.binding.remarkTv.setEnabled(false);
        }
    }

